insert into public.clubs (slug, name, short_name, tagline, description, category, color, member_count, founded_year, external_link, instagram_link, leads, tags, featured) values ('10x-club', '10X Club', '10X', 'Level up by 10x every single day', '10X Club is AIT''s flagship growth and productivity club. We believe in compounding improvement — workshops on productivity, personal development, tech deep-dives, and building the mindset to grow 10x every year.', 'technical', '#C8902E', 120, 2021, null, 'https://instagram.com', '[{"name":"Joyce Malik","role":"President"},{"name":"Arjun Shetty","role":"Secretary"}]'::jsonb, array['Productivity', 'Growth', 'Workshops', 'Tech']::text[], true);
insert into public.clubs (slug, name, short_name, tagline, description, category, color, member_count, founded_year, external_link, instagram_link, leads, tags, featured) values ('gdg-ait', 'GDG AIT', 'GDG', 'Google Developer Group at AIT', 'Google Developer Group at Dr. AIT — a community for developers who are interested in Google''s developer technology. We run workshops, study jams, hackathons, and connect students to the global GDG community.', 'technical', '#3F6E8C', 200, 2019, 'https://gdg.community.dev', 'https://instagram.com', '[{"name":"Rahul Nair","role":"Lead"},{"name":"Priya Sharma","role":"Co-Lead"}]'::jsonb, array['Google', 'Android', 'Cloud', 'Web', 'AI/ML']::text[], true);
insert into public.clubs (slug, name, short_name, tagline, description, category, color, member_count, founded_year, external_link, instagram_link, leads, tags, featured) values ('nextion-x', 'Nextion X', 'NX', 'Building the next generation of innovators', 'Nextion X is AIT''s innovation and entrepreneurship club. We bridge the gap between ideas and execution — startup pitches, incubation support, design thinking workshops, and industry mentorship.', 'technical', '#6B4A7A', 85, 2022, null, 'https://instagram.com', '[{"name":"Akash Reddy","role":"President"},{"name":"Sneha Joshi","role":"VP"}]'::jsonb, array['Startup', 'Innovation', 'Design Thinking', 'Entrepreneurship']::text[], true);
insert into public.clubs (slug, name, short_name, tagline, description, category, color, member_count, founded_year, external_link, instagram_link, leads, tags, featured) values ('uav-club', 'UAV Club', 'UAV', 'We build things that fly', 'AIT''s drone and autonomous systems club. We design, build, and program UAVs from scratch — racing drones, fixed-wing aircraft, FPV builds, and autonomous flight controllers. If it flies, we''re obsessed with it.', 'technical', '#5E7A3A', 75, 2020, null, 'https://instagram.com', '[{"name":"Kavya Menon","role":"President"},{"name":"Rohan Das","role":"Chief Pilot"}]'::jsonb, array['Drones', 'FPV', 'Autonomous', 'Hardware', 'Flight']::text[], true);
insert into public.clubs (slug, name, short_name, tagline, description, category, color, member_count, founded_year, external_link, instagram_link, leads, tags, featured) values ('motor-sports', 'Motor Sports Club', 'MSC', 'Built for speed. Driven by passion.', 'AIT''s Motor Sports Club builds and races formula-style vehicles, go-karts, and off-road buggies. We compete in national BAJA SAE, Formula Bharat, and Go-Kart Championship events. Mechanics, designers, and drivers all welcome.', 'sports', '#B5532E', 110, 2018, null, 'https://instagram.com', '[{"name":"Vikram Singh","role":"Team Captain"},{"name":"Divya Krishnan","role":"Chief Engineer"}]'::jsonb, array['BAJA SAE', 'Formula', 'Go-Kart', 'Mechanical', 'Racing']::text[], true);
insert into public.clubs (slug, name, short_name, tagline, description, category, color, member_count, founded_year, external_link, instagram_link, leads, tags, featured) values ('ait-robotics', 'AIT Robotics', 'ROBO', 'Building intelligent machines', 'AIT Robotics Club brings together students passionate about robotics, embedded systems, and automation. We build robots, participate in national competitions, and run hands-on hardware workshops.', 'technical', '#A8642A', 60, 2023, null, null, '[{"name":"Suresh Kumar","role":"Lead"},{"name":"Ananya Pillai","role":"Co-Lead"}]'::jsonb, array['Robotics', 'IoT', 'Embedded Systems', 'Arduino', 'ROS']::text[], false);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'gdg-ait'), 'Android Development Workshop', 'A hands-on workshop on building Android apps with Kotlin and Jetpack Compose. Bring your laptop. Beginners welcome.', 'workshop', ((current_date + 3) + time '16:00') at time zone 'Asia/Kolkata', ((current_date + 3) + time '18:00') at time zone 'Asia/Kolkata', 'CS Lab 3, Block A', '#', 60, array['Android', 'Kotlin', 'Jetpack Compose']::text[], true);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = '10x-club'), '10X Weekly Standup', 'Weekly accountability standup. Share what you built, learned, or achieved this week.', 'meeting', ((current_date + 1) + time '17:00') at time zone 'Asia/Kolkata', ((current_date + 1) + time '17:45') at time zone 'Asia/Kolkata', 'Seminar Hall 2', null, null, array['Productivity', 'Weekly']::text[], false);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'motor-sports'), 'Go-Kart Assembly Session', 'Weekly chassis assembly and brake-testing session for our BAJA SAE vehicle. All branches welcome — mechanics, electricals, designers.', 'practice', ((current_date + 0) + time '15:00') at time zone 'Asia/Kolkata', ((current_date + 0) + time '18:00') at time zone 'Asia/Kolkata', 'Motor Sports Workshop, Block D', null, null, array['BAJA SAE', 'Build', 'Mechanical']::text[], false);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'nextion-x'), 'Smart India Hackathon — Internal Qualifier', 'AIT''s internal qualifier for Smart India Hackathon 2026. Form teams of 4–6, pick a problem statement, and present your solution. Top 3 teams represent AIT at SIH nationals.', 'hackathon', ((current_date + 13) + time '09:00') at time zone 'Asia/Kolkata', ((current_date + 13) + time '21:00') at time zone 'Asia/Kolkata', 'Innovation Lab, Block C', '#', 120, array['Hackathon', 'SIH', 'Innovation']::text[], true);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'nextion-x'), 'Startup Pitch Day', 'Present your startup idea to a panel of mentors and investors. 5-minute pitch + 5-minute Q&A. Cash prizes for top 3 ideas.', 'competition', ((current_date + 7) + time '14:00') at time zone 'Asia/Kolkata', ((current_date + 7) + time '17:00') at time zone 'Asia/Kolkata', 'Auditorium', '#', 30, array['Startup', 'Pitch', 'Entrepreneurship']::text[], true);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'gdg-ait'), 'Cloud Study Jam — GCP', 'Guided study jam on Google Cloud Platform. Complete labs, earn badges. Free tier accounts provided.', 'workshop', ((current_date + 10) + time '15:00') at time zone 'Asia/Kolkata', ((current_date + 10) + time '17:30') at time zone 'Asia/Kolkata', 'CS Lab 1', '#', 50, array['Cloud', 'GCP', 'DevOps']::text[], false);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'ait-robotics'), 'Robotics Workshop — Intro to ROS', 'Introduction to Robot Operating System (ROS 2). Hands-on session with actual robot hardware.', 'workshop', ((current_date + 6) + time '10:00') at time zone 'Asia/Kolkata', ((current_date + 6) + time '13:00') at time zone 'Asia/Kolkata', 'Robotics Lab', '#', 20, array['Robotics', 'ROS', 'Hardware']::text[], false);
insert into public.events (club_id, title, description, type, starts_at, ends_at, venue, registration_link, max_seats, tags, featured) values ((select id from public.clubs where slug = 'uav-club'), 'FPV Night Flying — Open Demo', 'LED-rigged FPV quads flying after dark, with goggles to try on. Come watch, or bring your own quad for a supervised flight. No experience needed.', 'social', ((current_date + 9) + time '18:00') at time zone 'Asia/Kolkata', ((current_date + 9) + time '20:00') at time zone 'Asia/Kolkata', 'Open Air Amphitheatre', null, 200, array['Drones', 'FPV', 'Demo']::text[], true);
insert into public.announcements (club_id, title, body, priority, pinned, author_name, created_at) values ((select id from public.clubs where slug = 'nextion-x'), 'SIH Internal Qualifier — Registrations Close Tonight', 'Last chance to register for the Smart India Hackathon internal qualifier. Registrations close at 11:59 PM. Form your team of 4–6 and register via the link below. Problem statements are now live.', 'urgent', true, 'Akash Reddy', ((current_date + 0) + time '14:00') at time zone 'Asia/Kolkata');
insert into public.announcements (club_id, title, body, priority, pinned, author_name, created_at) values ((select id from public.clubs where slug = 'gdg-ait'), 'Android Workshop — Seats Almost Full', 'Only 17 seats remaining for the Android Development Workshop this week. Register now to confirm your spot. Bring your laptop with Android Studio installed.', 'important', false, 'Rahul Nair', ((current_date + 0) + time '10:30') at time zone 'Asia/Kolkata');
insert into public.announcements (club_id, title, body, priority, pinned, author_name, created_at) values ((select id from public.clubs where slug = 'motor-sports'), 'BAJA SAE — Chassis Build Schedule Updated', 'Assembly sessions now start at 3:00 PM on Sundays (shifted from 2:00 PM). Engine testing will be done on Wednesdays. Come to Block D workshop if you want to join the build team.', 'info', false, 'Vikram Singh', ((current_date + -1) + time '18:00') at time zone 'Asia/Kolkata');
insert into public.announcements (club_id, title, body, priority, pinned, author_name, created_at) values ((select id from public.clubs where slug = '10x-club'), '10X Weekly — This Week''s Theme: Deep Work', 'This week''s standup theme is Deep Work. Come prepared to share your strategy for distraction-free focused work. Cal Newport''s Deep Work chapter summary will be discussed.', 'info', false, 'Joyce Malik', ((current_date + -1) + time '09:00') at time zone 'Asia/Kolkata');
insert into public.announcements (club_id, title, body, priority, pinned, author_name, created_at) values ((select id from public.clubs where slug = 'ait-robotics'), 'Robotics Workshop — Pre-reading Material Released', 'Pre-reading material for the ROS 2 workshop has been uploaded. Please go through the ROS 2 basics PDF before the session this weekend. Hands-on time will be more productive if you''re familiar with the concepts.', 'info', false, 'Suresh Kumar', ((current_date + -2) + time '16:00') at time zone 'Asia/Kolkata');
insert into public.announcements (club_id, title, body, priority, pinned, author_name, created_at) values ((select id from public.clubs where slug = 'uav-club'), 'FPV Night Flying — Guest Pilots Confirmed', 'Two guest FPV pilots from the Bengaluru drone racing circuit will fly LED-rigged quads at our night demo. Bring your own quad if you have one; we''ll have spare batteries and a safety briefing at 5:45.', 'important', false, 'Kavya Menon', ((current_date + -3) + time '11:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Aditya Rao', '3rd Sem CSE', 'Does anyone have DBMS PYQs from 2023–24?', 'Looking for previous year question papers for DBMS (3rd sem CSE). I''ve checked the library but couldn''t find them. Any Google Drive links would be super helpful.', 'academic', 'CSE', array['DBMS', 'PYQ', 'CSE', '3rd Sem']::text[], false, true, ((current_date + 0) + time '08:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Meera Iyer', '5th Sem CSE', 'Anyone interested in teaming up for SIH?', 'Looking for 3 more people to form a team for the SIH internal qualifier. I have experience in ML and backend. Looking for frontend dev + hardware/IoT person + domain expert. DM me or reply here.', 'projects', 'Hackathons', array['SIH', 'Hackathon', 'Team', 'ML']::text[], true, false, ((current_date + -1) + time '22:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Krishnam Murty', '4th Sem CSE', 'Which electives should I take in 5th sem?', 'Choosing between Machine Learning, Computer Networks, and Cryptography. Any seniors who''ve taken these? Which one has better scope for placements and actual learning?', 'academic', 'CSE', array['Electives', '5th Sem', 'Placements']::text[], false, false, ((current_date + -2) + time '15:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Tanvir Ahmed', '4th Sem ECE', 'Should we start a robotics club for ECE students?', 'ECE students barely get a chance to work on actual robotics projects. The existing Robotics Club is mostly CSE-focused. Should we petition for a separate ECE-oriented robotics and embedded systems club?', 'campus', 'Clubs', array['ECE', 'Robotics', 'New Club', 'Embedded']::text[], false, false, ((current_date + -3) + time '13:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Pooja Kulkarni', '3rd Sem ISE', 'Best resources to learn React from scratch?', 'Complete beginner to web dev. Tried a couple of YouTube tutorials but they go too fast. Any structured roadmap or resource you''d recommend for someone starting React in 2026?', 'career', 'Web Development', array['React', 'Web Dev', 'Resources', 'Beginners']::text[], false, true, ((current_date + -4) + time '11:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Nikita Jain', '5th Sem ISE', 'Can GDG conduct a Flutter workshop?', 'I know GDG focuses on Android native, but Flutter is cross-platform and a lot of us want to learn it. Can GDG add a Flutter workshop to their schedule? I know at least 40 students who''d attend.', 'campus', 'Clubs', array['Flutter', 'GDG', 'Workshop Request']::text[], false, false, ((current_date + -5) + time '09:00') at time zone 'Asia/Kolkata');
insert into public.discussions (author_name, author_year, title, body, category, subcategory, tags, pinned, solved, created_at) values ('Rohan Patil', '4th Sem CSE', 'How do college placements actually work here?', '4th sem student — super confused about the placement process at AIT. When does CGPA matter? Which companies come? What''s the eligibility cutoff? Any seniors who can share a clear breakdown?', 'career', 'Placements', array['Placements', 'CGPA', 'Career', 'Seniors']::text[], false, true, ((current_date + -6) + time '20:00') at time zone 'Asia/Kolkata');
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('Smart India Hackathon 2026', 'hackathon', 'Government of India / AICTE', current_date + 24, 'All undergraduate students', '₹1,00,000 for winners', null, 'India''s biggest national level hackathon. Solve real problems faced by central & state government ministries. 36-hour nonstop coding event.', '#', array['National', 'Government', '36hr']::text[], true);
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('Google Summer of Code 2027', 'internship', 'Google', current_date + 133, 'Students 18+', null, '$3000–$6600 USD', 'Work with an open source organization on a 3-month programming project. One of the most prestigious student programs in tech.', '#', array['Open Source', 'Google', 'Remote', 'Stipend']::text[], true);
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('ISRO Young Scientist Programme', 'research', 'ISRO', current_date + 70, '1st–3rd year UG students', null, null, 'Spend 2 weeks at an ISRO centre and work on real space technology problems. One of India''s most prestigious student research programs.', '#', array['Space', 'ISRO', 'Research', 'National']::text[], true);
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('Microsoft AI Classroom Series', 'certification', 'Microsoft', current_date + 101, 'Any student', null, null, 'Free Azure AI certification training for students. Complete online modules, earn a Microsoft certification. Fully remote.', '#', array['AI', 'Microsoft Azure', 'Free', 'Certification']::text[], false);
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('National Robotics Championship', 'competition', 'AICTE', current_date + 29, 'Teams of 3–5 engineering students', '₹50,000 + trophy', null, 'Build and program a robot to complete a set of challenges. Autonomous + manual control rounds. Categories: line following, obstacle avoidance, arena battle.', '#', array['Robotics', 'Hardware', 'Teams', 'AICTE']::text[], false);
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('Goldman Sachs Engineering Virtual Internship', 'internship', 'Goldman Sachs', current_date + 40, 'Pre-final year CSE/ISE students', null, 'Paid', 'Virtual internship focusing on software engineering, quantitative finance, and data science. Hands-on tasks, mentorship, and real-world experience.', '#', array['Finance', 'Software', 'Virtual', 'Pre-final Year']::text[], false);
insert into public.opportunities (title, type, organizer, deadline, eligibility, prize, stipend, description, link, tags, featured) values ('INSPIRE Scholarship — DST', 'scholarship', 'Department of Science & Technology', current_date + 41, 'Students in top 1% of 10+2', null, '₹80,000/year', 'Scholarship for exceptional students pursuing basic or natural sciences. Covers tuition, living allowance, and research grants.', '#', array['Scholarship', 'Government', 'Science']::text[], false);
